"""从已入库独立审核提取自写参考，并只读绑定原公开题面与后台六字段。"""
import ast,copy,html,json,re,sys
from pathlib import Path
sys.path.insert(0,str(Path.cwd()/'scripts'));import repair_gmyhf_pending_answers as c
mapping={27699:(8,'wide_swap')}
keys={'描述':'description','输入':'input','输出':'output','提示':'hint','样例输入':'sampleInput','样例输出':'sampleOutput'}
session=c.platform.oj_submit.Session().login()
for n,(batch,function) in mapping.items():
 original=Path(f'collab/gmyhf-pending-batch{batch}-review.json');data=json.loads(original.read_text());old=next(e for e in data['entries'] if e['global_number']==n)['authored_reference'];assert c.sha(old['source'].encode())==old['sha256'];proc=old;tree=ast.parse(proc['source'])
 entry=copy.deepcopy(next(e for e in data['entries'] if e['global_number']==n));public_page=Path(entry['page']).read_bytes();assert c.sha(public_page)==entry['page_sha256']
 section=re.search(r'<dl class="problem-content">(.*?)</dl>',public_page.decode(),re.S)[1];public={k:'' for k in keys.values()}
 for label,value in re.findall(r'<dt>(.*?)</dt>\s*<dd>(.*?)</dd>',section,re.S):
  if label not in keys:continue
  public[keys[label]]=value[5:-6] if value.startswith('<pre>') and value.endswith('</pre>') else value
 fields=c.platform.parse_form(session._get(c.platform.oj_submit.HOST+f'/admin/problems/edit/?id={n}'))
 def canonical(s):return html.unescape(s).replace('\xa0',' ').replace('\r\n','\n').strip()
 modes={}
 for key in public:
  a,b=canonical(public[key]),canonical(fields[key]);mode='raw'
  if a!=b:
   a=re.sub(r'<br\s*/?>','\n',a);b=re.sub(r'<br\s*/?>','\n',b);mode='br_as_newline'
  if a!=b:
   import difflib
   print(n,key,'diff',repr('\n'.join(difflib.unified_diff(a.splitlines(),b.splitlines()))[:1600]),flush=True)
  assert a==b,(n,key)
  modes[key]=mode
 node=next(v for v in tree.body if isinstance(v,ast.FunctionDef) and v.name==function);body=ast.get_source_segment(proc['source'],node)
 source=Path('/tmp/gmyhf_wide_swap_reference.cpp').read_text()
 entry['authored_reference']={'source':source,'sha256':c.sha(source.encode()),'language':'cpp','origin':'原独立审核自产Python函数的自写C++翻译，未取用平台附件；小域穷举与原函数对拍另有证明。','original_python_source':old['source'],'original_python_sha256':old['sha256'],'function_sha256':c.sha(body.encode())}
 entry['checks']['statement']['field_sha256']={k:c.sha(html.unescape(fields[k]).encode()) for k in public}
 s=Path(__file__).read_text();c.save(Path(f'/tmp/gmyhf-{n}-authored-admin-review.json'),{'original_evidence':str(original),'original_evidence_sha256':c.sha(original.read_bytes()),'public_page_sha256':c.sha(public_page),'comparison_modes':modes,'scope':'独立审核自产函数按原源码哈希提取；公开题面六字段与后台一致（pre包装、行尾、边缘空白、NBSP与空格和已标明的br换行），绑定当前后台原字段哈希。','platform_writes':0,'procedure_source':s,'procedure_sha256':c.sha(s.encode()),'entries':[entry]})
 print(n,'自写参考溯源及后台题面绑定通过',flush=True)

