// 原独立审核自写线段树参考的C++翻译，未使用平台附件源码。
#include <algorithm>
#include <iostream>
#include <queue>
#include <utility>
#include <vector>
using namespace std;
vector<int> solve_wide(int n,int k,vector<int> a) {
    int size=1; while(size<n) size*=2;
    vector<pair<int,int>> tree(2*size,{0,-1});
    for(int i=0;i<n;i++) tree[size+i]={a[i],i};
    for(int i=size-1;i;i--) tree[i]=max(tree[2*i],tree[2*i+1]);
    auto query=[&](int left,int right) {
        left=max(0,left)+size; right=min(n,right)+size;
        pair<int,int> best={0,-1};
        while(left<right) {
            if(left&1) best=max(best,tree[left++]);
            if(right&1) best=max(best,tree[--right]);
            left/=2;right/=2;
        }
        return best;
    };
    auto available=[&](int i) {return a[i] && query(i-k+1,i+k).first==a[i];};
    priority_queue<int> heap;
    for(int i=0;i<n;i++) if(available(i)) heap.push(i);
    vector<int> answer(n);int label=n;
    while(!heap.empty()) {
        int i=heap.top();heap.pop();if(!a[i]) continue;
        answer[i]=label--;a[i]=0;
        int at=size+i;tree[at]={0,-1};
        while(at>1) {at/=2;tree[at]=max(tree[2*at],tree[2*at+1]);}
        for(auto range:vector<pair<int,int>>{{i-k+1,i},{i+1,i+k}}) {
            auto best=query(range.first,range.second);
            if(best.first && available(best.second)) heap.push(best.second);
        }
    }
    if(label!=0) throw 1;
    return answer;
}
int main() {
    ios::sync_with_stdio(false);cin.tie(nullptr);
    int n,k;if(!(cin>>n>>k))return 1;
    vector<int>a(n);for(int &x:a)cin>>x;
    auto answer=solve_wide(n,k,a);
    for(int i=0;i<n;i++)cout<<(i?" ":"")<<answer[i];
    cout<<'\n';
}
